\u0046\u0044\u0033\u0055\u003c\u0026\u0046\u0038\u0040\u0056\u006c\u0039\u0024\u0072\u003f\u002c\u005a\u0045\u0042\u002e\u007a\u002c\u0052\u0024\u007e\u0033\u0037\u0059\u0035\u0048\u005f\u0078\u0031\u003f\u0042\u0069\u0054\u0055\u0066\u007d\u0070\u006d\u0076\u006f\u0072\u005e\u0056\u0049\u0039\u0078\u006b\u0067\u003b\u0041\u002e\u007c\u002e\u0077\u0054\u007e\u0032\u003b\u0039\u0075\u005f\u006e\u0079\u0062\u0025\u0050\u0024\u0079\u007e\u005a\u0074\u0049\u0025\u004d\u0031\u006d\u0070\u0038\u0058\u002b\u0036\u0079\u0040\u007e\u002e\u0026\u0051\u003e\u0035\u006d\u0056\u0045\u007c\u004a\u003b\u0068\u0037\u0052\u003f\u007d\u0059\u005b\u004e\u0068\u0054\u0035\u007d\u0025\u0067\u0044\u0073\u0071\u0029\u0034\u0040\u006f\u0026\u0054\u0037\u0071\u0059\u0052\u005f\u007d\u0046\u0041\u0043\u0054\u0039\u005e\u0022\u0046\u0066\u0059\u002a\u007d\u0066\u007e\u007b\u002f\u0059\u0069\u0024\u002f\u005f\u005a\u0057\u0059\u0032\u004d\u007a\u0064\u0070\u0046\u005b\u0054\u0073\u0039\u0057\u0040\u005e\u007e\u003c\u0070\u005a\u0062\u0059\u0021\u0026\u0046\u004b\u0037\u0029\u0063\u003e\u003e\u0072\u0031\u0067\u0062\u0032\u0063\u003c\u0068\u0031\u006d\u0038\u004a\u0023\u006d\u0036\u005e\u005f\u0069\u0074\u007d\u007d\u005d\u0057\u0059\u002e\u006b\u006c\u007b\u0039\u007d\u004c\u006f\u003e\u0032\u0046\u006b\u0068\u0055\u006d\u0079\u004a\u007e\u0069\u002e\u0029\u007a\u0030\u004d\u0071\u0025\u0023\u0042\u0069\u0036\u0045\u0031\u006b\u003a\u005a\u0071\u0023\u0057\u0049\u003e\u0061\u007d\u0054\u0035\u0050\u0043\u0030\u006c\u0059\u007e\u0059\u007e\u002c\u0040\u0069\u002e\u0022\u003a\u0067\u0059\u0071\u0026\u0072\u0037\u005f\u0040\u007b\u0054\u0043\u005a\u002e\u003c\u0060\u0026\u006f\u0039\u0038\u0078\u003c\u003f\u004b\u0059\u006c\u0050\u0061\u006f\u007b\u0077\u002f\u0036\u0062\u0040\u005d\u007e\u004e\u0064\u0036\u0072\u003c\u0054\u004e\u0058\u0038\u002b\u007e\u0064\u0025\u0057\u0034\u0057\u0059\u003b\u003e\u006e\u0064\u0062\u006b\u0072\u002e\u0039\u0051\u006d\u0039\u0028\u0029\u0046\u0070\u002e\u0021\u0063\u0067\u0052\u002f\u0045\u002f\u0037\u0046\u0033\u007c\u0064\u003e\u0039\u006d\u0031\u0039\u0029\u0024\u0076\u0072\u002b\u0070\u0063\u0049\u0043\u005b\u0059\u0031\u0041\u0067\u0070\u0038\u0039\u0044\u0065\u002e\u007e\u003a\u0038\u006d\u0031\u0032\u004b\u0032\u002c\u0043\u0066\u0025\u006e\u0046\u0048\u0024\u0043\u002e\u003b\u005a\u002c\u0079\u007e\u0053\u007d\u0029\u0063\u0029\u006d\u0056\u0023\u004c\u005d\u0079\u0049\u0043\u0064\u0047\u0071\u004d\u0072\u0053\u002f\u0030\u002e\u0079\u0065\u0025\u0052\u0069\u006a\u0070\u0075\u004e\u0046\u0065\u005e\u0054\u0056\u0029\u005e\u0024\u0059\u0022\u003d\u004b\u0072\u003e\u006b\u0045\u0077\u0053\u0065\u0046\u0074\u0051\u0029\u006d\u0071\u0026\u006d\u0075\u0029\u005b\u0051\u0056\u0049\u0032\u003d\u005f\u0059\u006f\u002c\u007a\u0066\u0069\u0046\u0025\u0067\u0038\u006d\u005b\u0069\u005d\u004d\u0025\u0078\u0075\u0044\u002e\u004b\u002c\u0065\u0063\u004b\u0059\u006e\u0038\u0032\u002a\u003e\u0040\u007e\u0036\u005e\u002c\u005d\u0023\u006d\u0065\u0038\u0066\u0070\u005d\u003d\u0076\u0079\u007b\u0021\u002f\u0043\u004d\u0057\u0048\u0041\u006e\u0030\u0070\u0079\u004a\u006f\u0053\u006d\u0036\u0028\u0023\u0025\u005e\u0032\u003d\u0078\u005b\u0026\u002a\u0075\u0054\u0024\u0036\u002e\u0049\u0069\u0033\u002a\u0049\u0061\u0070\u0050\u0045\u006e\u0047\u0065\u0062\u0055\u0071\u0034\u0043\u0067\u004d\u003b\u007a\u0043\u0067\u0026\u0070\u0066\u0047\u003e\u0052\u0023\u006e\u0074\u0071\u0070\u0062\u0069\u0025\u0074\u0031\u003c\u0076\u0074\u0075\u0075\u002b\u0047\u0023\u0045\u0074\u0026\u0024\u0037\u0065\u003c\u006c\u0067\u006d\u0031\u007b\u003f\u004a\u0054\u0071\u0028\u0021\u0029\u007d\u004c\u002e\u0045\u004a\u0021\u0067\u0034\u0040\u003a\u0045\u0022\u004b\u0043\u0069\u0049\u0063\u0070\u007e\u0026\u0062\u0041\u0031\u005d\u006b\u006d\u0072\u002f\u003e\u002a\u0079\u0043\u0066\u002b\u0042\u006d\u004b\u004e\u0062\u0066\u0031\u002b\u0071\u0039\u0067\u0047\u0079\u0053\u0059\u0065\u0079\u007a\u0078\u003d\u0074\u006c\u007d\u006b\u0038\u003e\u0065\u0074\u005a\u0068\u007b\u0072\u0024\u004b\u0046\u0051\u0023\u0060\u0076\u006a\u0033\u0069\u0046\u006f\u006c\u003a\u0063\u0031\u002a\u0061\u004e\u002f\u0070\u0063\u0043\u005f\u0063\u0077\u0032\u003c\u0033\u003e\u0063\u006b\u0076\u0079\u005a\u0040\u0047\u0062\u002c\u0078\u0037\u002a\u0032\u0031\u002b\u0052\u0037\u0063\u002a\u0066\u0033\u0061\u005d\u0075\u0043\u0079\u0063\u0069\u006b\u004f\u0052\u0064\u0036\u0067\u0076\u005a\u003e\u0041\u007b\u0047\u0043\u0038\u0079\u0061\u004e\u0068\u0052\u006f\u005b\u005a\u003b\u007a\u0070\u0064\u0064\u0048\u002b\u002a\u0063\u0025\u003a\u0045\u005f\u007d\u004a\u0078\u003b\u005e\u0045\u003f\u0050\u006e\u0022\u0028\u0065\u0048\u0021\u0078\u0036\u004d\u0066\u002c\u004c\u003c\u003f\u0025\u0064\u0060\u0069\u0022\u0048\u0057\u0069\u0055\u0048\u0026\u003b\u005b\u0075\u0058\u0044\u006e\u006f\u0071\u0065\u003a\u006f\u002b\u0064\u0060\u0069\u0022\u0048\u0057\u0069\u0055\u0048\u0026\u003b\u005b\u0047\u003d\u007c\u0055\u004e\u004e\u004a\u0026\u0060\u002a\u0041\u0060\u0024\u005f\u0030\u0071\u0068\u0061\u003f\u0021\u007a\u0061\u0031\u003d\u004a\u0065\u0034\u0036\u0036\u003b\u0051\u0067\u0039\u0048\u003d\u004d\u0033\u0044\u003c\u007a\u0048\u0029\u0032\u0067\u0024\u0042\u0060\u0046\u0024\u0048\u005b\u0074\u0078\u0044\u0056\u002f\u003a\u006d\u005d\u007e\u0058\u0057\u0046\u0071\u0065\u0045\u004b\u0045\u0061\u007c\u004a\u005b\u002f\u0052\u0023\u006b\u0061\u007c\u0030\u0054\u003c\u002c\u0025\u0028\u0043\u004a\u0030\u0064\u0038\u0052\u0062\u0023\u0052\u0063\u0042\u0072\u0039\u006f\u007d\u0039\u0078\u002f\u007d\u006e\u0065\u0077\u002c\u0060\u0026\u0067\u006b\u0060\u0075\u0026\u002c\u0074\u0022\u004e\u0040\u0021\u0063\u0073\u0046\u002e\u003e\u0026\u0025\u007d\u0025\u0032\u0069\u0054\u0070\u0045\u0074\u0033\u0050\u006a\u0050\u002b\u0053\u006b\u002a\u003d\u0032\u0077\u003a\u002f\u0068\u0061\u0075\u0041\u0042\u005e\u005e\u005a\u0035\u007e\u0059\u003a\u002f\u0068\u0061\u0075\u0041\u0047\u004f\u0076\u0040\u0048\u0073\u004e\u0048\u0074\u007b\u0025\u0037\u0033\u002e\u0066\u006c\u006f\u0062\u0023\u002f\u0067\u0039\u002f\u007c\u006c\u002a\u0051\u0053\u003e\u0026\u0024\u004d\u0045\u0030\u0057\u004c\u0054\u0038\u007a\u0023\u0079\u0068\u002c\u007b\u0078\u007d\u004e\u0053\u003f\u0075\u0038\u002a\u006d\u0039\u007a\u006c\u0023\u0023\u004a\u0023\u0043\u0028\u005f\u0023\u0059\u0077\u0024\u0074\u002e\u0066\u0079\u0033\u0031\u002a\u0031\u003e\u0079\u0055\u006b\u0052\u0028\u0058\u003a\u006d\u0066\u005f\u003f\u002e\u0022\u0060\u006e\u0028\u0077\u0036\u004c\u0051\u0060\u0030\u0076\u003b\u0060\u005b\u002f\u0043\u005a\u0034\u0066\u0032\u0063\u002a\u002a\u005d\u004e\u0039\u0069\u0063\u0075\u0030\u007a\u0051\u0051\u004d\u0055\u005f\u0056\u0051\u0060\u0032\u0077\u004b\u0050\u0030\u004b\u003a\u0051\u0034\u0057\u0072\u007a\u0043\u005b\u0039\u0057\u006b\u003f\u0031\u0056\u0078\u0073\u007e\u0077\u007e\u0021\u0041\u0070\u0031\u0067\u0032\u0071\u0036\u004d\u0039\u004d\u0050\u0036\u0047\u003e\u006f\u0022\u0071\u002b\u0078\u006e\u0056\u0025\u0032\u004b\u004f\u0078\u0051\u0051\u002c\u0029\u004a\u0036\u0021\u002b\u0054\u0039\u0049\u006d\u004c\u004e\u0028\u0055\u0030\u0060\u0070\u0064\u006b\u006e\u003e\u0035\u0024\u0073\u0045\u0037\u006e\u0021\u005e\u0040\u002b\u0077\u0042\u0079\u006b\u0034\u005d\u0079\u0051\u007c\u005f\u002a\u0034\u0068\u005a\u0034\u004f\u0057\u002e\u007e\u007d\u004d\u007a\u0041\u007b\u0051\u0036\u0044\u0057\u002e\u007e\u007d\u004d\u004b\u0041\u007e\u005e\u005a\u0057\u0038\u007b\u0065\u0044\u005a\u003e\u0066\u0074\u005a\u002a\u003f\u002e\u0032\u005e\u007c\u003b\u0041\u0076\u0022\u0031\u003a\u0056\u0074\u007c\u0048\u0079\u007b\u0042\u0060\u0022\u004d\u0058\u0067\u0076\u004f\u0064\u0030\u0041\u006d\u0028\u0054\u0049\u005e\u007e\u0043\u0044\u004b\u005e\u0068\u0059\u0038\u0066\u004b\u007b\u004f\u0068\u0065\u0030\u0065\u0065\u004a\u005a\u0059\u003c\u0072\u0036\u0077\u006d\u004d\u0068\u0064\u0074\u0049\u003f\u0065\u0025\u005d\u0059\u007d\u0065\u0024\u0065\u005e\u007a\u0072\u002e\u005e\u0043\u0039\u003c\u0022\u0064\u0054\u0053\u003e\u0079\u0029\u0055\u0022\u0064\u0054\u0053\u003e\u0041\u0079\u0078\u0042\u0051\u006c\u007e\u002a\u0079\u0041\u005b\u0074\u006c\u0052\u0036\u0052\u005e\u002c\u0037\u007e\u0031\u0072\u0035\u0024\u004e\u0045\u0034\u0052\u003e\u007d\u002e\u005d\u0057\u0040\u005d\u006b\u0044\u004d\u0037\u0052\u0051\u0067\u007d\u0075\u0032\u0054\u0070\u004a\u0059\u003f\u0032\u0039\u0044\u0036\u0072\u0024\u0022\u0052\u0035\u0033\u0050\u004e\u004e\u0068\u0077\u0025\u0051\u0051\u0064\u0069\u0041\u0045\u0061\u005b\u0062\u004a\u004c\u0074\u002f\u002f\u0052\u0044\u0034\u0074\u0040\u0076\u0076\u005a\u0029\u0044\u005a\u0059\u003a\u0069\u0045\u005e\u004c\u005b\u0076\u005a\u0034\u0044\u002b\u0022\u003a\u0028\u005f\u004b\u0051\u0021\u003c\u0023\u0044\u0040\u0035\u0078\u0046\u0077\u004f\u0064\u006f\u0050\u0038\u0061\u006c\u0034\u003e\u0076\u0060\u002a\u0043\u0053\u0036\u0060\u006a\u0060\u0042\u0035\u0035\u0039\u0057\u002e\u0038\u0066\u0077\u0036\u0048\u003f\u0022\u002c\u0040\u0029\u0059\u0050\u003e\u007b\u004e\u0062\u005d\u0057\u004d\u0037\u0040\u002f\u0046\u003a\u006d\u006d\u0021\u0023\u003a\u003d\u0047\u0047\u005d\u006b\u003e\u004a\u0047\u0072\u0063\u0041\u0034\u0026\u0064\u0036\u004e\u0062\u0039\u0037\u007b\u0028\u0035\u0061\u0035\u007b\u004d\u0021\u0048\u0038\u0038\u0031\u0035\u007b\u0043\u0043\u0076\u0063\u003f\u0079\u007e\u0035\u0031\u0074\u0042\u0067\u005f\u0047\u007b\u007a\u002c\u0071\u004d\u004c\u003a\u002b\u0039\u005d\u0029\u0050\u004a\u004f\u0025\u0034\u0021\u0056\u0076\u0060\u002a\u0043\u0022\u007d\u0021\u0054\u0030\u0021\u0054\u0058\u0054\u007c\u0051\u004c\u004e\u0068\u003f\u0028\u005b\u004e\u0031\u004a\u007a\u0062\u0070\u0028\u0047\u002f\u003a\u0062\u0033\u004f\u0024\u003f\u0073\u0072\u0044\u0052\u0048\u005e\u004f\u0045\u0034\u0073\u0031\u006a\u0032\u006b\u0070\u0053\u0047\u0035\u0078\u0058\u003c\u0044\u0030\u0021\u0041\u006e\u002c\u0074\u0052\u003a\u0034\u006d\u006d\u002f\u002a\u0068\u0042\u003b\u0045\u0040\u0030\u0030\u0073\u0045\u0053\u0079\u0075\u0026\u003d\u0051\u003d\u0066\u0058\u0069\u0077\u0036\u0044\u0045\u0077\u006b\u005b\u0048\u007e\u005b\u0077\u003f\u0026\u004f\u003e\u0045\u005f\u0077\u0066\u0045\u0032\u0021\u0057\u006b\u0052\u005b\u0056\u0046\u006e\u006f\u0062\u007d\u005b\u0050\u0054\u003b\u005f\u006a\u0076\u0051\u0073\u005d\u004d\u0021\u0042\u0046\u0055\u0056\u0036\u0071\u0078\u007b\u006d\u0034\u0063\u0058\u006a\u007e\u0056\u0075\u006e\u0031\u0039\u0032\u0021\u0076\u0051\u0037\u0022\u005b\u0077\u0024\u006c\u004d\u002b\u0036\u0052\u0071\u0032\u0073\u0048\u0078\u0033\u005a\u0066\u0024\u0038\u005d\u0029\u0070\u007d\u0057\u0021\u0078\u004f\u0036\u005e\u0051\u003b\u004a\u002c\u0077\u0022\u0055\u0046\u0031\u0079\u004d\u0063\u0059\u0044\u0079\u0041\u0060\u004c\u006c\u0040\u0061\u0046\u0055\u0062\u0062\u0079\u004d\u006a\u0025\u002a\u006f\u004d\u0037\u0063\u004b\u0035\u0041\u002b\u006f\u004d\u0028\u002b\u0053\u0075\u0032\u003d\u004c\u006b\u0064\u004d\u003d\u0046\u003d\u005e\u006f\u0021\u0077\u005f\u0069\u0051\u0068\u006c\u007d\u0030\u0051\u0033\u0060\u0045\u0067\u0063\u0062\u003a\u0049\u0070\u0050\u005b\u0078\u0058\u0036\u0039\u002f\u0073\u005b\u0056\u0046\u006e\u0075\u0038\u003a\u0078\u006e\u0030\u0025\u0053\u0049\u003e\u0052\u005b\u0023\u0071\u0077\u0046\u004f\u002e\u002b\u0043\u0050\u0076\u0045\u005a\u0079\u0030\u0051\u0033\u0060\u004d\u0060\u007b\u0042\u0054\u0034\u0073\u0067\u0076\u0045\u007d\u0079\u0068\u0052\u006d\u0047\u0053\u003e\u005b\u0074\u0054\u0034\u0055\u005b\u0057\u0045\u006e\u006c\u0054\u0052\u005b\u0023\u006c\u0068\u0040\u0075\u0054\u002c\u0065\u0056\u006a\u0025\u0032\u0031\u0075\u0053\u0038\u004b\u0058\u0070\u0033\u0068\u0052\u0062\u0076\u002f\u0060\u0053\u0070\u005b\u0023\u0077\u0038\u007c\u005f\u006a\u0063\u0022\u0037\u003f\u0051\u002f\u005e\u004e\u0066\u0056\u0073\u003d\u0067\u007a\u0062\u0070\u0054\u0052\u0055\u0043\u0023\u0042\u0023\u005a\u0039\u0047\u0066\u0021\u004e\u0070\u006d\u0055\u0040\u006d\u004f\u0078\u0060\u002a\u0048\u0046\u0071\u0024\u0052\u0022\u004f\u0077\u004e\u0029\u005f\u0042\u0075\u007d\u004d\u0047\u0061\u0069\u007a\u0057